{
  "title": "The Rescue of the Lost Heir",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A summons reaches the rescue party at dawn.",
      "visual_description": "A small camp at the edge of a misty forest, with a rolled parchment held up to the rising sun, distant ruined spires on the horizon.",
      "characters": ["Captain Renna", "Brother Oslin"]
    },
    {
      "scene_number": 2,
      "caption": "The party studies a tattered map of the ruined city.",
      "visual_description": "Four figures crouched around a faded map on a tree stump, marked with red ink crosses and burned edges.",
      "characters": ["Captain Renna", "Brother Oslin", "Wisp the Sparrow-Mage", "Tobin the Scout"]
    },
    {
      "scene_number": 3,
      "caption": "They approach the broken castle gates.",
      "visual_description": "Massive iron gates split in half, vines crawling over fallen statues, banners of a dead royal house fluttering in tatters.",
      "characters": ["Captain Renna", "Tobin the Scout"]
    },
    {
      "scene_number": 4,
      "caption": "Frightened townspeople warn of patrols.",
      "visual_description": "Hooded villagers huddled in a doorway of a half-collapsed bakery, pointing nervously down a cobbled lane.",
      "characters": ["Captain Renna", "Brother Oslin", "Old Maren the Baker"]
    },
    {
      "scene_number": 5,
      "caption": "An armored patrol marches past their hiding place.",
      "visual_description": "Black-armored soldiers with spears tramping along a rubble-strewn avenue, seen through a cracked window from above.",
      "characters": ["Tobin the Scout", "Wisp the Sparrow-Mage"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon stir in the marketplace ruins.",
      "visual_description": "An empty market square with overturned stalls, a single scorched scale glinting on the cobblestones, smoke curling in the distance.",
      "characters": ["Captain Renna", "Old Maren the Baker"]
    },
    {
      "scene_number": 7,
      "caption": "Wisp casts a seeking spell to find the prisoner.",
      "visual_description": "A small sparrow-shaped mage holding a glowing blue feather aloft, threads of light weaving toward a distant tower.",
      "characters": ["Wisp the Sparrow-Mage", "Brother Oslin"]
    },
    {
      "scene_number": 8,
      "caption": "The cursed tower looms over the inner courtyard.",
      "visual_description": "A leaning black tower wrapped in spectral chains, violet runes pulsing along its base, crows wheeling overhead.",
      "characters": ["Captain Renna", "Tobin the Scout", "Wisp the Sparrow-Mage"]
    },
    {
      "scene_number": 9,
      "caption": "Tobin scales the outer wall to scout entry.",
      "visual_description": "A wiry figure climbing crumbled masonry with a rope coiled at the belt, gargoyles leering from above.",
      "characters": ["Tobin the Scout"]
    },
    {
      "scene_number": 10,
      "caption": "They confront a magic door sealed with sigils.",
      "visual_description": "A tall stone door covered in shifting silver glyphs, faintly humming, set into the side of the tower.",
      "characters": ["Wisp the Sparrow-Mage", "Brother Oslin", "Captain Renna"]
    },
    {
      "scene_number": 11,
      "caption": "Brother Oslin sleepily mumbles the counter-prayer.",
      "visual_description": "A round-bellied cleric yawning mid-incantation, his lantern swinging, glyphs on the door dimming one by one.",
      "characters": ["Brother Oslin", "Captain Renna"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, they pass torn royal banners and dust.",
      "visual_description": "A long ruined hallway with sun-faded crimson banners hanging in shreds, a broken throne visible at the far end.",
      "characters": ["Captain Renna", "Brother Oslin", "Tobin the Scout", "Wisp the Sparrow-Mage"]
    },
    {
      "scene_number": 13,
      "caption": "They find Princess Aleya chained in the tower cell.",
      "visual_description": "A small barred chamber with a young woman in a torn gown chained to a stone ring, moonlight slanting through a slit window.",
      "characters": ["Princess Aleya", "Captain Renna", "Tobin the Scout"]
    },
    {
      "scene_number": 14,
      "caption": "Wisp shatters the enchanted chains.",
      "visual_description": "Bright blue sparks bursting from severed iron links, the sparrow-mage hovering with wings spread wide.",
      "characters": ["Wisp the Sparrow-Mage", "Princess Aleya"]
    },
    {
      "scene_number": 15,
      "caption": "An armored patrol blocks the stairway down.",
      "visual_description": "A narrow spiral stair filled with helmed soldiers, torches reflecting off their visors, weapons raised.",
      "characters": ["Captain Renna", "Princess Aleya", "Tobin the Scout", "Brother Oslin"]
    },
    {
      "scene_number": 16,
      "caption": "A dragon roars overhead, scattering the soldiers.",
      "visual_description": "A great red dragon plunging from the night sky above the courtyard, soldiers diving for cover as flame licks the stones.",
      "characters": ["Captain Renna", "Princess Aleya", "Wisp the Sparrow-Mage"]
    },
    {
      "scene_number": 17,
      "caption": "The party flees toward the river bridge.",
      "visual_description": "Five running figures silhouetted against firelight, racing down a sloping street toward an arched stone bridge over dark water.",
      "characters": ["Captain Renna", "Princess Aleya", "Brother Oslin", "Tobin the Scout", "Wisp the Sparrow-Mage"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge as dawn breaks behind them.",
      "visual_description": "The group walking across a long stone bridge with the burning city receding behind, pale gold sunrise on the far shore.",
      "characters": ["Captain Renna", "Princess Aleya", "Brother Oslin", "Tobin the Scout", "Wisp the Sparrow-Mage"]
    }
  ]
}

